import type { Candle, Dataset, Timeframe } from './types';

/**
 * Seeded synthetic OHLCV generator.
 *
 * Honesty rule (bible §8): the FUTURE part of a scenario is never shaped to reward a decision.
 * Past regimes may be scripted (to tell a story: trend → topping → panic), but every candle after the
 * decision point is generated by a zero-drift process with the same volatility model. Tests assert this.
 */

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  let u = 0;
  let v = 0;
  while (u === 0) u = rnd();
  while (v === 0) v = rnd();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

export interface Regime {
  /** Number of candles in this regime. */
  bars: number;
  /** Drift per bar (log return). Must be 0 for every regime after the decision point. */
  drift: number;
  /** Volatility per bar (std of log return). */
  vol: number;
  /** Volume multiplier. */
  volume: number;
}

export const TF_SECONDS: Record<Timeframe, number> = { '15m': 900, '1h': 3600, '4h': 14400, '1d': 86400 };

export interface GenOptions {
  seed: number;
  start: number;
  startTime: number;
  timeframe: Timeframe;
  regimes: Regime[];
  baseVolume: number;
  /** Intrabar sub-steps used to build realistic highs/lows. */
  substeps?: number;
}

export function generate(opts: GenOptions): Candle[] {
  const rnd = mulberry32(opts.seed);
  const sub = opts.substeps ?? 12;
  const out: Candle[] = [];
  let price = opts.start;
  let t = opts.startTime;
  let volState = 1;
  for (const r of opts.regimes) {
    for (let i = 0; i < r.bars; i++) {
      const o = price;
      let h = o;
      let l = o;
      let p = o;
      let absMove = 0;
      // Volatility clustering (GARCH-like), bounded.
      volState = Math.min(2.2, Math.max(0.6, 0.85 * volState + 0.15 * (0.7 + rnd() * 0.9)));
      const sigma = (r.vol * volState) / Math.sqrt(sub);
      for (let k = 0; k < sub; k++) {
        const step = r.drift / sub + sigma * gauss(rnd);
        p = p * Math.exp(step);
        absMove += Math.abs(step);
        if (p > h) h = p;
        if (p < l) l = p;
      }
      const c = p;
      const v = opts.baseVolume * r.volume * (0.55 + rnd() * 0.5) * (1 + (absMove / (r.vol + 1e-9)) * 0.35);
      out.push({ t, o: round(o), h: round(h), l: round(l), c: round(c), v: Math.round(v) });
      price = c;
      t += TF_SECONDS[opts.timeframe];
    }
  }
  return out;
}

function round(x: number): number {
  return Math.round(x * 100) / 100;
}

/**
 * Story session "0417 — Kapitulacja" for Dave's journal:
 * a slow uptrend, a topping phase, then a fast sell-off with a volume climax at the decision point.
 * After the decision: zero drift (unknown direction), elevated but decaying volatility.
 */
export const SESSION_0417_REGIMES: Regime[] = [
  { bars: 34, drift: 0.0042, vol: 0.011, volume: 1.0 },
  { bars: 14, drift: -0.0004, vol: 0.013, volume: 1.15 },
  { bars: 10, drift: -0.012, vol: 0.022, volume: 1.9 },
  { bars: 2, drift: -0.03, vol: 0.03, volume: 3.4 },
  // ---- decision point here (index 59) ----
  { bars: 10, drift: 0, vol: 0.024, volume: 2.0 },
  { bars: 18, drift: 0, vol: 0.016, volume: 1.2 },
];

export function session0417(seed = 417): Dataset {
  const candles = generate({
    seed,
    start: 412.8,
    startTime: Date.UTC(2031, 2, 3, 0, 0, 0) / 1000,
    timeframe: '4h',
    regimes: SESSION_0417_REGIMES,
    baseVolume: 18500,
  });
  return {
    meta: {
      id: 'mcx-0417-synthetic',
      symbol: 'MCX/USD',
      name: 'Margin City Exchange Composite (fikcyjny)',
      market: 'Indeks fikcyjny',
      venue: 'MARGIN CITY EXCHANGE (fikcja)',
      timeframe: '4h',
      timezone: 'UTC',
      currency: 'USD',
      source: 'Generator syntetyczny (seed 417) — NIE są to notowania rynkowe',
      synthetic: true,
      license: 'Dane wygenerowane na potrzeby gry — brak ograniczeń',
      note: 'Przyszłe świece generowane procesem bez dryfu: nie są dobierane pod wynik decyzji.',
    },
    candles,
  };
}

/** Random training sessions (same honesty rule, different seeds). */
export function trainingSession(seed: number): Dataset {
  const rnd = mulberry32(seed * 7919);
  const pick = <T,>(a: T[]) => a[Math.floor(rnd() * a.length)];
  const past: Regime[] = [
    { bars: 20 + Math.floor(rnd() * 12), drift: pick([0.004, -0.004, 0.0005]), vol: 0.01 + rnd() * 0.006, volume: 1 },
    { bars: 12 + Math.floor(rnd() * 10), drift: pick([0.006, -0.008, 0, 0.002]), vol: 0.012 + rnd() * 0.01, volume: 1.2 + rnd() },
  ];
  const used = past.reduce((a, r) => a + r.bars, 0);
  past.push({ bars: Math.max(4, 60 - used), drift: pick([0.003, -0.003, 0]), vol: 0.012, volume: 1.1 });
  const ds = generate({
    seed,
    start: 80 + rnd() * 400,
    startTime: Date.UTC(2031, 0, 1) / 1000 + Math.floor(rnd() * 200) * 86400,
    timeframe: '4h',
    regimes: [...past, { bars: 28, drift: 0, vol: 0.015, volume: 1.1 }],
    baseVolume: 12000 + rnd() * 20000,
  });
  return {
    meta: {
      id: `training-${seed}`,
      symbol: 'DEMO/USD',
      name: 'Instrument treningowy (fikcyjny)',
      market: 'Fikcyjny',
      venue: 'Symulacja',
      timeframe: '4h',
      timezone: 'UTC',
      currency: 'USD',
      source: `Generator syntetyczny (seed ${seed}) — NIE są to notowania rynkowe`,
      synthetic: true,
      license: 'Dane wygenerowane na potrzeby gry — brak ograniczeń',
    },
    candles: ds,
  };
}
